import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { ensureFrontmatterValue, readFrontmatter, updateFrontmatterValue } from "../../frontmatter";
import {
  DEFAULT_TICKET_STATUSES,
  TICKET_STATUSES,
  type TicketDependency,
  type TicketInfo,
  type TicketStatus,
} from "./constants";
import { compareTicketIds, compareTickets } from "./sorting";

const isDirectory = (path: string): boolean => {
  try {
    return statSync(path).isDirectory();
  } catch {
    return false;
  }
};

export const findSchubRoot = (startDir: string = process.cwd()): string | null => {
  let current = resolve(startDir);

  while (true) {
    const candidate = join(current, ".schub");
    if (existsSync(candidate) && isDirectory(candidate)) {
      return candidate;
    }

    const parent = dirname(current);
    if (parent === current) {
      return null;
    }
    current = parent;
  }
};

const isTicketFolder = (dirPath: string, fileName: string): boolean => {
  const match = fileName.match(/^(TK\d+)_(.+)$/);
  if (!match) return false;

  const ticketMdPath = join(dirPath, fileName, "ticket.md");
  try {
    return existsSync(ticketMdPath) && statSync(ticketMdPath).isFile();
  } catch {
    return false;
  }
};

const parseTicketFolderName = (folderName: string): { id: string; title: string } | null => {
  const underscoreIndex = folderName.indexOf("_");
  if (underscoreIndex <= 0) return null;

  const id = folderName.slice(0, underscoreIndex);
  if (!/^(T|TK)\d+$/.test(id)) return null;

  const titleSlug = folderName.slice(underscoreIndex + 1);
  return { id, title: titleSlug.replace(/-/g, " ") };
};

const getTicketFilePath = (ticketsRoot: string, folderName: string): string => {
  return join(ticketsRoot, folderName, "ticket.md");
};

const _getTicketArtifactsPath = (ticketsRoot: string, folderName: string): string => {
  return join(ticketsRoot, folderName);
};

type ParsedTicketFile = {
  id: string;
  title: string;
  status: TicketStatus;
  dependsOn: string[];
  changeId?: string;
  checklistRemaining?: number;
  checklistTotal?: number;
  blockedReason?: string;
};

const parseTicketStatus = (value: unknown) => {
  if (typeof value !== "string") {
    return null;
  }

  const normalized = value.trim().toLowerCase();
  if (normalized === "in_review") {
    return "reviewed" as const;
  }

  if (TICKET_STATUSES.includes(normalized as TicketStatus)) {
    return normalized as TicketStatus;
  }

  return null;
};

const parseChecklistCounts = (content: string) => {
  const lines = content.split(/\r?\n/);
  let inSteps = false;
  let checklistTotal = 0;
  let checklistRemaining = 0;

  for (const line of lines) {
    const headingMatch = line.match(/^##\s+(.*)$/);
    if (headingMatch) {
      const heading = headingMatch[1].trim().toLowerCase();
      if (heading === "steps") {
        inSteps = true;
      } else if (inSteps) {
        break;
      }
      continue;
    }

    if (!inSteps) {
      continue;
    }

    const checklistMatch = line.match(/^\s*-\s+\[( |x|X)\]/);
    if (!checklistMatch) {
      continue;
    }

    checklistTotal += 1;
    if (checklistMatch[1].toLowerCase() !== "x") {
      checklistRemaining += 1;
    }
  }

  if (checklistTotal === 0) {
    return null;
  }

  return {
    checklistRemaining,
    checklistTotal,
  };
};

const extractTitle = (content: string, id: string) => {
  const headerMatch = content.match(/^#+\s+(.*)$/m);
  if (headerMatch?.[1]) {
    return headerMatch[1].trim();
  }

  const body = content.replace(/^---[\s\S]*?---/, "").trim();
  const firstLine = body.split("\n")[0].trim();
  if (firstLine.length > 0) {
    return firstLine.length > 60 ? `${firstLine.slice(0, 57)}...` : firstLine;
  }

  return id;
};

const parseTicketFile = (filePath: string, fallback: { id: string; title: string }): ParsedTicketFile => {
  let content = "";
  try {
    content = readFileSync(filePath, "utf8");
  } catch {
    return { ...fallback, status: "backlog", dependsOn: [] };
  }

  const title = extractTitle(content, fallback.id);
  const { data } = readFrontmatter(content);
  const status = parseTicketStatus(data.status) ?? "backlog";
  const changeIdValue = data.change_id;
  const changeId = typeof changeIdValue === "string" ? changeIdValue.trim() : undefined;

  const dependsValue = data.depends_on;
  let dependsOn: string[] = [];
  if (Array.isArray(dependsValue)) {
    dependsOn = dependsValue.map((value) => value.trim()).filter(Boolean);
  } else if (typeof dependsValue === "string" && dependsValue.trim()) {
    dependsOn = [dependsValue.trim()];
  }

  const blockedReasonValue = data.blocked_reason;
  const blockedReason =
    typeof blockedReasonValue === "string" && blockedReasonValue.trim() ? blockedReasonValue.trim() : undefined;
  const checklistCounts = parseChecklistCounts(content);

  return {
    id: fallback.id,
    title,
    status,
    dependsOn,
    changeId,
    blockedReason: blockedReason || undefined,
    ...(checklistCounts ?? {}),
  };
};
type TicketFileEntry = {
  id: string;
  title: string;
  status: TicketStatus;
  path: string;
  parsedFile: ParsedTicketFile;
};

const loadTicketFiles = (schubDir: string, statuses: readonly TicketStatus[] = DEFAULT_TICKET_STATUSES) => {
  const ticketsRoot = join(schubDir, "tickets");
  if (!existsSync(ticketsRoot) || !isDirectory(ticketsRoot)) {
    return [];
  }

  const allowed = new Set(statuses);
  const repoRoot = dirname(schubDir);
  const tickets: TicketFileEntry[] = [];

  const entries = readdirSync(ticketsRoot, { withFileTypes: true });

  for (const entry of entries) {
    if (!entry.isDirectory()) {
      continue;
    }

    if (!isTicketFolder(ticketsRoot, entry.name)) {
      continue;
    }

    const parsed = parseTicketFolderName(entry.name);
    if (!parsed) continue;

    const filePath = getTicketFilePath(ticketsRoot, entry.name);
    const parsedFile = parseTicketFile(filePath, parsed);

    if (!allowed.has(parsedFile.status)) {
      continue;
    }

    tickets.push({
      id: parsed.id,
      title: parsed.title,
      status: parsedFile.status,
      path: relative(repoRoot, filePath),
      parsedFile,
    });
  }

  return tickets;
};
export const listTickets = (
  schubDir: string,
  statuses: readonly TicketStatus[] = DEFAULT_TICKET_STATUSES,
): TicketInfo[] => {
  const tickets = loadTicketFiles(schubDir, statuses).map((ticket) => ({
    id: ticket.id,
    title: ticket.title,
    status: ticket.status,
    path: ticket.path,
    checklistRemaining: ticket.parsedFile.checklistRemaining,
    checklistTotal: ticket.parsedFile.checklistTotal,
    blockedReason: ticket.parsedFile.blockedReason,
  }));

  return tickets.sort(compareTickets);
};

export const loadTicketDependencies = (
  schubDir: string,
  statuses: readonly TicketStatus[] = DEFAULT_TICKET_STATUSES,
): TicketDependency[] => {
  const tickets = loadTicketFiles(schubDir, statuses).map((ticket) => {
    const dependsOn = ticket.parsedFile.dependsOn.sort(compareTicketIds);

    return {
      id: ticket.id,
      title: ticket.title,
      status: ticket.status,
      path: ticket.path,
      dependsOn,
      changeId: ticket.parsedFile.changeId,
      checklistRemaining: ticket.parsedFile.checklistRemaining,
      checklistTotal: ticket.parsedFile.checklistTotal,
      blockedReason: ticket.parsedFile.blockedReason,
    };
  });

  return tickets.sort(compareTickets);
};

export const listTicketsForChange = (
  schubDir: string,
  changeId: string,
  statuses: readonly TicketStatus[] = DEFAULT_TICKET_STATUSES,
) => {
  const normalizedChangeId = changeId.trim();
  const tickets = loadTicketFiles(schubDir, statuses)
    .filter((ticket) => ticket.parsedFile.changeId === normalizedChangeId)
    .map((ticket) => ({
      id: ticket.id,
      title: ticket.title,
      status: ticket.status,
      path: ticket.path,
      changeId: ticket.parsedFile.changeId,
      checklistRemaining: ticket.parsedFile.checklistRemaining,
      checklistTotal: ticket.parsedFile.checklistTotal,
      blockedReason: ticket.parsedFile.blockedReason,
    }));

  return tickets.sort(compareTickets);
};

export const clearTicketsForChange = (schubDir: string, changeId: string) => {
  const normalizedChangeId = changeId.trim();
  if (!normalizedChangeId) {
    throw new Error("Provide --proposal-id.");
  }

  const repoRoot = dirname(schubDir);
  const tickets = loadTicketFiles(schubDir, TICKET_STATUSES);
  const cleared: string[] = [];

  for (const ticket of tickets) {
    if (ticket.parsedFile.changeId !== normalizedChangeId) {
      continue;
    }

    const filePath = join(repoRoot, ticket.path);
    const content = readFileSync(filePath, "utf8");
    const { data } = readFrontmatter(content);

    if (typeof data.change_id !== "string") {
      continue;
    }

    const updated = updateFrontmatterValue(content, "change_id", "");
    writeFileSync(filePath, updated, "utf8");
    cleared.push(ticket.id);
  }

  return cleared;
};

type TicketUpdateStatus = TicketStatus;

const updateTicketFileStatus = (ticketPath: string, status: TicketUpdateStatus) => {
  const frontmatterStatus = status === "reviewed" ? "in_review" : status;
  const content = readFileSync(ticketPath, "utf8");
  let updated = content;

  try {
    updated = updateFrontmatterValue(content, "status", frontmatterStatus);
  } catch {
    updated = ensureFrontmatterValue(content, "status", frontmatterStatus);
  }

  if (updated !== content) {
    writeFileSync(ticketPath, updated, "utf8");
  }
};

export const updateTicketStatuses = (
  schubDir: string,
  ticketIds: string[],
  status: TicketUpdateStatus,
): TicketInfo[] => {
  const repoRoot = dirname(schubDir);
  const sourceTickets = listTickets(schubDir, TICKET_STATUSES);
  const ticketsById = new Map(sourceTickets.map((ticket) => [ticket.id, ticket]));

  return ticketIds
    .map((ticketId) => ticketsById.get(ticketId))
    .filter((ticket): ticket is TicketInfo => Boolean(ticket))
    .map((ticket) => {
      const currentPath = join(repoRoot, ticket.path);
      updateTicketFileStatus(currentPath, status);

      return {
        ...ticket,
        status,
        path: ticket.path,
      };
    });
};

const ACTIVE_TICKET_STATUSES = TICKET_STATUSES.filter((status) => status !== "archived" && status !== "rejected");

export const assignTicketToWip = (schubDir: string, ticketId: string): TicketInfo => {
  const normalizedId = ticketId.trim().toUpperCase();
  if (!normalizedId) {
    throw new Error("Provide --id.");
  }

  const repoRoot = dirname(schubDir);
  const ticket = listTickets(schubDir, ACTIVE_TICKET_STATUSES).find((active) => active.id === normalizedId);
  if (!ticket) {
    throw new Error(`Ticket ${normalizedId} not found.`);
  }

  updateTicketFileStatus(join(repoRoot, ticket.path), "wip");

  return {
    ...ticket,
    status: "wip",
  };
};

export const archiveTicketsForChange = (schubDir: string, changeId: string) => {
  const normalizedChangeId = changeId.trim();
  const repoRoot = dirname(schubDir);
  const tickets = loadTicketDependencies(schubDir, ACTIVE_TICKET_STATUSES).filter(
    (ticket) => ticket.changeId === normalizedChangeId,
  );

  return tickets.map((ticket) => {
    const currentPath = join(repoRoot, ticket.path);
    updateTicketFileStatus(currentPath, "archived");

    return {
      ...ticket,
      status: "archived",
      path: ticket.path,
    };
  });
};

