test("detail view exposes open and copy shortcuts for tickets", async () => {
  const baseDir = mkdtempSync(join(tmpdir(), "schub-app-detail-shortcuts-"));
  const changesRoot = join(baseDir, ".schub", "proposals");
  const backlogRoot = join(baseDir, ".schub", "tickets", "backlog");
  const changeId = "C1401_detail-actions";
  let copied = "";

  mkdirSync(changesRoot, { recursive: true });
  mkdirSync(backlogRoot, { recursive: true });

  writeDetailedProposal(changesRoot, changeId, "Draft", "Detail action summary.");
  writeTicket(
    backlogRoot,
    "T1400",
    "detail-ticket",
    `---\nchange_id: ${changeId}\n---\n# Ticket: T1400 Detail Ticket\n\n## Notes\n\nHello detail\n`,
  );

  const rendered = render(
    <App
      startDir={baseDir}
      copyToClipboard={(value) => {
        copied = value;
      }}
    />,
  );

  await settleFrames();
  rendered.stdin.write("\n");
  await settleFrames();

  const detailOutput = stripAnsi(rendered.lastFrame() ?? "");
  expect(detailOutput).not.toContain("[o preview]");
  expect(detailOutput).toContain("[c copy id]");
  expect(detailOutput).toContain("[s status]");

  rendered.stdin.write("c");
  await settleFrames();
  expect(copied).toBe("T1400");

  rendered.stdin.write("o");
  await settleFrames();

  const ignoredOutput = stripAnsi(rendered.lastFrame() ?? "");
  expect(ignoredOutput).not.toContain("T1400_detail-ticket.md");
  expect(ignoredOutput).toContain("Proposal Detail");

  rendered.stdin.write("\n");
  await settleFrames();

  const previewOutput = stripAnsi(rendered.lastFrame() ?? "");
  expect(previewOutput).toContain("T1400_detail-ticket.md");
  expect(previewOutput).toContain("Hello detail");
});

