test("launches worktree implement with SCHUB_CWD override", async () => {
  const originalProjectId = process.env.SCHUB_PROJECT_ID;
  process.env.SCHUB_PROJECT_ID = "project-0701";

  const baseDir = mkdtempSync(join(tmpdir(), "schub-app-implement-worktree-"));
  const reviewedRoot = join(baseDir, ".schub", "tickets", "reviewed");
  const doneRoot = join(baseDir, ".schub", "tickets", "done");
  const changeId = "C0701_app-context";
  const changeRoot = join(baseDir, ".schub", "proposals", changeId);
  const worktreePath = join(baseDir, ".schub", "worktrees", "T0701");

  mkdirSync(reviewedRoot, { recursive: true });
  mkdirSync(doneRoot, { recursive: true });
  mkdirSync(join(changeRoot, "notes"), { recursive: true });

  writeTicket(doneRoot, "T0700", "done-ticket", "# Ticket: T0700 Done Ticket\n");
  const ticketContent = [
    "---",
    `change_id: "${changeId}"`,
    "depends_on:",
    "  - T0700",
    "---",
    "# Ticket: T0701 Reviewed Ticket",
    "",
  ].join("\n");
  writeTicket(reviewedRoot, "T0701", "reviewed-ticket", ticketContent);
  writeFileSync(join(changeRoot, "a-summary.md"), "Summary", "utf8");
  writeFileSync(join(changeRoot, "b-details.md"), "Details", "utf8");
  writeFileSync(join(changeRoot, "notes", "c-extra.md"), "Extra", "utf8");

  const expectedPrompt = [
    ticketContent.trimEnd(),
    "# a-summary.md\n\nSummary",
    "# b-details.md\n\nDetails",
    "# c-extra.md\n\nExtra",
  ].join("\n\n");

  mockCreateWorktree.mockReturnValue({ worktreePath, branchName: "ticket/T0701", gitRoot: baseDir });

  try {
    const rendered = render(<App startDir={baseDir} />);
    await settleFrames();
    rendered.stdin.write("i");
    await settleFrames();
    rendered.stdin.write("\u001B[B");
    await settleFrames();
    rendered.stdin.write("\n");
    await settleFrames();

    expect(mockCreateWorktree).toHaveBeenCalledWith({
      repoRoot: baseDir,
      ticketId: "T0701",
      projectId: "project-0701",
    });
    expect(mockLaunchImplement).toHaveBeenCalledTimes(1);

    const [ticketId, repoRoot, options, overrides] = (mockLaunchImplement.mock.calls[0] ?? []) as LaunchImplementArgs;
    expect(ticketId).toBe("T0701");
    expect(realpathSync(repoRoot)).toBe(realpathSync(baseDir));
    expect(options?.prompt).toBe(expectedPrompt);
    expect(overrides?.env?.SCHUB_CWD).toBe(worktreePath);
    expect(overrides?.cwd).toBe(worktreePath);
  } finally {
    if (originalProjectId === undefined) {
      delete process.env.SCHUB_PROJECT_ID;
    } else {
      process.env.SCHUB_PROJECT_ID = originalProjectId;
    }
  }
});

