import { afterEach, expect, mock, test } from "bun:test";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { render as inkRender } from "ink-testing-library";
import packageJson from "../../package.json";
import type { launchOpencodeImplement } from "../executors/opencode";
import { findSchubRoot } from "../features/tickets";
import type { createTicketWorktree } from "../features/tickets/worktree";
import App from "./app";

const resolvedStartDir = process.env.SCHUB_CWD ?? process.cwd();
const schubDir = findSchubRoot(resolvedStartDir);
const homeDir = homedir();
const displaySchubDir = (() => {
  const targetDir = schubDir ?? resolvedStartDir;
  if (targetDir === homeDir) {
    return "~";
  }
  if (targetDir.startsWith(`${homeDir}/`)) {
    return `~${targetDir.slice(homeDir.length)}`;
  }
  return targetDir;
})();

const ansiPattern = new RegExp(`${String.fromCharCode(27)}[[0-9;]*m`, "g");
const stripAnsi = (value: string) => value.replace(ansiPattern, "");
const settleFrames = async () => {
  await new Promise((resolve) => setTimeout(resolve, 0));
  await new Promise((resolve) => setTimeout(resolve, 0));
};

const createMockChild = () => {
  const child = {
    unref: () => {},
    once: () => child,
  };

  return child;
};

type LaunchImplementArgs = Parameters<typeof launchOpencodeImplement>;
type CreateWorktreeArgs = Parameters<typeof createTicketWorktree>;

const mockLaunchImplement = mock<(...args: LaunchImplementArgs) => ReturnType<typeof launchOpencodeImplement>>(
  (..._args) => createMockChild(),
);
const mockCreateWorktree = mock<(..._args: CreateWorktreeArgs) => ReturnType<typeof createTicketWorktree>>(() => null);

mock.module("../executors/opencode", () => ({
  launchOpencodeImplement: mockLaunchImplement,
  launchOpencodeCreateTickets: () => createMockChild(),
  launchOpencodeReview: () => createMockChild(),
  listOpencodeSessions: () => [],
  selectLatestSessionMatch: () => null,
  exportOpencodeSession: () => ({ session: { id: "", title: "", directory: "", updatedAt: "" }, messages: [] }),
  mapOpencodeSessionSummary: () => ({ id: "", title: "", directory: "", updatedAt: "", messages: [] }),
}));

mock.module("../features/tickets/worktree", () => ({
  createTicketWorktree: mockCreateWorktree,
}));

const renders: Array<() => void> = [];
const render = (...args: Parameters<typeof inkRender>) => {
  const rendered = inkRender(...args);
  renders.push(rendered.unmount);
  return rendered;
};

afterEach(() => {
  for (const unmount of renders) {
    unmount();
  }
  renders.length = 0;
  mockLaunchImplement.mockClear();
  mockCreateWorktree.mockClear();
  mockCreateWorktree.mockImplementation(() => null);
});

