  process.env.SCHUB_PROJECT_ID = "project-0711";

  const baseDir = mkdtempSync(join(tmpdir(), "schub-app-implement-worktree-error-"));
  const ticketsRoot = join(baseDir, ".schub", "tickets");

  mkdirSync(ticketsRoot, { recursive: true });

  writeTicket(ticketsRoot, "T0710", "done-ticket", "---\nstatus: done\n---\n# Ticket: T0710 Done Ticket\n");
  writeTicket(
    ticketsRoot,
    "T0711",
    "reviewed-ticket",
    "---\nstatus: reviewed\ndepends_on:\n  - T0710\n---\n# Ticket: T0711 Reviewed Ticket\n",
  );

  mockCreateWorktree.mockImplementation(() => {
    throw new Error("Worktree failed");
  });

  try {
    const rendered = render(<App startDir={baseDir} />);
    await settleFrames();
    rendered.stdin.write("i");
    await settleFrames();
    rendered.stdin.write("\u001B[B");
    await settleFrames();
    rendered.stdin.write("\n");
    await settleFrames();

    expect(mockLaunchImplement).not.toHaveBeenCalled();

    const output = stripAnsi(rendered.lastFrame() ?? "");
    expect(output).toContain("Worktree failed");
    expect(output).toContain("esc");

    rendered.stdin.write("\u001B");
    await settleFrames();

    const closed = stripAnsi(rendered.lastFrame() ?? "");
    expect(closed).not.toContain("Worktree failed");
  } finally {
    if (originalProjectId === undefined) {
      delete process.env.SCHUB_PROJECT_ID;
    } else {
      process.env.SCHUB_PROJECT_ID = originalProjectId;
    }
  }
});

