import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { ensureFrontmatterValue, readFrontmatter, updateFrontmatterValue } from "../../frontmatter";
import {
  DEFAULT_TICKET_STATUSES,
  TICKET_STATUSES,
  type TicketDependency,
  type TicketInfo,
  type TicketStatus,
} from "./constants";
import { compareTicketIds, compareTickets } from "./sorting";

const isDirectory = (path: string): boolean => {
  try {
    return statSync(path).isDirectory();
  } catch {
    return false;
  }
};

export const findSchubRoot = (startDir: string = process.cwd()): string | null => {
  let current = resolve(startDir);

  while (true) {
    const candidate = join(current, ".schub");
    if (existsSync(candidate) && isDirectory(candidate)) {
      return candidate;
    }

    const parent = dirname(current);
    if (parent === current) {
      return null;
    }
    current = parent;
  }
};

