  id: string;
  title: string;
  status: TicketStatus;
  path: string;
  parsedFile: ParsedTicketFile;
};

const loadTicketFiles = (schubDir: string, statuses: readonly TicketStatus[] = DEFAULT_TICKET_STATUSES) => {
