    const parsed = parseTicketFolderName(entry.name);
    if (!parsed) continue;

    const filePath = getTicketFilePath(ticketsRoot, entry.name);
    const parsedFile = parseTicketFile(filePath, parsed);

    if (!allowed.has(parsedFile.status)) {
      continue;
    }

    tickets.push({
      id: parsed.id,
      title: parsed.title,
      status: parsedFile.status,
      path: relative(repoRoot, filePath),
      parsedFile,
    });
  }

  return tickets;
};
export const listTickets = (
  schubDir: string,
  statuses: readonly TicketStatus[] = DEFAULT_TICKET_STATUSES,
): TicketInfo[] => {
  const tickets = loadTicketFiles(schubDir, statuses).map((ticket) => ({
    id: ticket.id,
    title: ticket.title,
    status: ticket.status,
    path: ticket.path,
