};

export const listTicketsForChange = (
  schubDir: string,
  changeId: string,
  statuses: readonly TicketStatus[] = DEFAULT_TICKET_STATUSES,
) => {
  const normalizedChangeId = changeId.trim();
  const tickets = loadTicketFiles(schubDir, statuses)
    .filter((ticket) => ticket.parsedFile.changeId === normalizedChangeId)
    .map((ticket) => ({
