import { expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  buildChangeListItems,
  buildShowAllGroups,
  buildShowAllTicketGroups,
  buildStatusData,
  buildTicketListItems,
} from "./status-view-data";

const writeTicket = (ticketsRoot: string, id: string, slug: string, body: string) => {
  const folderPath = join(ticketsRoot, `${id}_${slug}`);
  mkdirSync(folderPath, { recursive: true });
  const filePath = join(folderPath, "ticket.md");
  writeFileSync(filePath, body, "utf8");
};

const writeProposal = (changesRoot: string, changeId: string, status: string, title = changeId) => {
  const changeDir = join(changesRoot, changeId);
  mkdirSync(changeDir, { recursive: true });
  writeFileSync(join(changeDir, "proposal.md"), `---\nstatus: ${status}\n---\n# Proposal - ${title}\n`, "utf8");
};

test("buildTicketListItems derives ready/draft statuses and progress", () => {
  const base = mkdtempSync(join(tmpdir(), "schub-status-list-tickets-"));
  const schubDir = join(base, ".schub");
  const ticketsRoot = join(schubDir, "tickets");

  mkdirSync(ticketsRoot, { recursive: true });

  writeTicket(ticketsRoot, "T3000", "draft-ticket", "-----
status: backlog
priority: [P1|P2|P3]
---
# Ticket: T3000 Draft Ticket
");
  writeTicket(ticketsRoot, "T3001", "backlog-ticket", "---\nstatus: backlog\n---\n# Ticket: T3001 Backlog Ticket\n");
  writeTicket(ticketsRoot, "T3002", "done-ticket", "---\nstatus: done\n---\n# Ticket: T3002 Done Ticket\n");
  writeTicket(
    ticketsRoot,
    "T3003",
    "ready-ticket",
    "---\nstatus: reviewed\ndepends_on:\n  - T3002\n---\n# Ticket: T3003 Ready Ticket\n",
  );
  writeTicket(
    ticketsRoot,
    "T3004",
    "waiting-ticket",
    "---\nstatus: reviewed\ndepends_on:\n  - T3999\n---\n# Ticket: T3004 Waiting Ticket\n",
  );
  writeTicket(ticketsRoot, "T3005", "wip-ticket", "---\nstatus: wip\n---\n# Ticket: T3005 Wip Ticket\n\n## Steps\n- [ ] First\n- [x] Second\n");

  const items = buildTicketListItems(schubDir);

  expect(items.find((item) => item.id === "T3000")).toMatchObject({
    id: "T3000",
    title: "draft ticket",
    status: "draft",
  });
  expect(items.find((item) => item.id === "T3001")).toMatchObject({
    id: "T3001",
    title: "backlog ticket",
    status: "backlog",
  });
  expect(items.find((item) => item.id === "T3003")).toMatchObject({
    id: "T3003",
    title: "ready ticket",
    status: "ready",
  });
  expect(items.find((item) => item.id === "T3004")).toMatchObject({
    id: "T3004",
    title: "waiting ticket",
    status: "reviewed",
  });
  expect(items.find((item) => item.id === "T3005")).toMatchObject({
    id: "T3005",
    title: "wip ticket",
    status: "wip",
    checklistProgress: { completed: 1, total: 2 },
  });
});

test("buildChangeListItems derives no-tickets and wip statuses", () => {
  const base = mkdtempSync(join(tmpdir(), "schub-status-list-changes-"));
  const schubDir = join(base, ".schub");
  const changesRoot = join(schubDir, "proposals");
  const backlogRoot = join(schubDir, "tickets", "backlog");
  const doneRoot = join(schubDir, "tickets", "done");

  mkdirSync(changesRoot, { recursive: true });
  mkdirSync(backlogRoot, { recursive: true });
  mkdirSync(doneRoot, { recursive: true });

  const pendingChange = "C4000_pending-work";
  const noTicketsChange = "C4001_no-tickets";

  writeProposal(changesRoot, pendingChange, "Accepted", "Pending Work");
  writeProposal(changesRoot, noTicketsChange, "Accepted", "No Tickets");

  writeTicket(
    backlogRoot,
    "T4000",
    "pending-ticket",
    `---\nchange_id: ${pendingChange}\n---\n# Ticket: T4000 Pending Ticket\n`,
  );
  writeTicket(doneRoot, "T4001", "done-ticket", `---\nchange_id: ${pendingChange}\n---\n# Ticket: T4001 Done Ticket\n`);

  const items = buildChangeListItems(schubDir);

  expect(items.find((item) => item.id === pendingChange)).toMatchObject({
    id: pendingChange,
    title: "Pending Work",
    status: "wip",
    ticketProgress: { completed: 1, total: 2 },
  });

  const noTicketsItem = items.find((item) => item.id === noTicketsChange);
  expect(noTicketsItem?.status).toBe("no-tickets");
  expect(noTicketsItem?.ticketProgress).toBeUndefined();
});

test("buildStatusData keeps ready tickets out of reviewed list", () => {
  const base = mkdtempSync(join(tmpdir(), "schub-status-ready-"));
  const schubDir = join(base, ".schub");
  const reviewedRoot = join(schubDir, "tickets", "reviewed");
  const doneRoot = join(schubDir, "tickets", "done");

  mkdirSync(reviewedRoot, { recursive: true });
  mkdirSync(doneRoot, { recursive: true });

  writeTicket(doneRoot, "T5000", "done-ticket", "# Ticket: T5000 Done Ticket\n");
  writeTicket(
    reviewedRoot,
    "T5001",
    "ready-ticket",
    "---\ndepends_on:\n  - T5000\n---\n# Ticket: T5001 Ready Ticket\n",
  );
  writeTicket(
    reviewedRoot,
    "T5002",
    "waiting-ticket",
    "---\ndepends_on:\n  - T5999\n---\n# Ticket: T5002 Waiting Ticket\n",
  );

  const { readyToImplement, reviewed } = buildStatusData(schubDir);

  expect(readyToImplement.map((ticket) => ticket.id)).toContain("T5001");
  expect(reviewed.map((ticket) => ticket.id)).not.toContain("T5001");
  expect(reviewed.map((ticket) => ticket.id)).toContain("T5002");
});

test("show-all views include rejected items while main view hides them", () => {
  const base = mkdtempSync(join(tmpdir(), "schub-status-rejected-"));
  const schubDir = join(base, ".schub");
  const backlogRoot = join(schubDir, "tickets", "backlog");
  const rejectedRoot = join(schubDir, "tickets", "rejected");
  const archivedChangesRoot = join(schubDir, "archive", "proposals");

  mkdirSync(backlogRoot, { recursive: true });
  mkdirSync(rejectedRoot, { recursive: true });

  writeTicket(backlogRoot, "T6001", "backlog-ticket", "# Ticket: T6001 Backlog Ticket\n");
  writeTicket(rejectedRoot, "T6000", "rejected-ticket", "# Ticket: T6000 Rejected Ticket\n");

  const changeId = "C6000_rejected-change";
  writeProposal(archivedChangesRoot, changeId, "Rejected", "Rejected Change");

  const statusData = buildStatusData(schubDir);
  const activeTicketIds = [...statusData.backlog, ...statusData.reviewed, ...statusData.wip, ...statusData.blocked].map(
    (ticket) => ticket.id,
  );

  expect(activeTicketIds).not.toContain("T6000");

  const showAllTicketGroups = buildShowAllTicketGroups(schubDir);
  const rejectedTicketGroup = showAllTicketGroups.find((group) => group.label === "Rejected");
  expect(rejectedTicketGroup?.items.map((item) => item.id)).toContain("T6000");

  const showAllGroups = buildShowAllGroups(schubDir);
  const rejectedChangeGroup = showAllGroups.find((group) => group.label === "Rejected");
  expect(rejectedChangeGroup?.items.map((item) => item.id)).toContain(changeId);

  const showAllItems = buildChangeListItems(schubDir, { includeArchived: true });
  expect(showAllItems.find((item) => item.id === changeId)?.status).toBe("rejected");
});

